function getAverages(nums, k) {
  const n = nums.length;
  const width = 2 * k + 1;
  const avgs = new Array(n).fill(-1);
  let windowSum = 0;

  for (let right = 0; right < n; right++) {
    windowSum += nums[right];
    if (right >= width) {
      windowSum -= nums[right - width];
    }
    if (right >= width - 1) {
      avgs[right - k] = Math.floor(windowSum / width);
    }
  }
  return avgs;
}

