function getAverages(nums, k) {
  const result = [];
  for (let i = 0; i < nums.length; i++) {
    if (i - k < 0 || i + k >= nums.length) { result.push(-1); continue; }
    let total = 0;
    for (let j = i - k; j <= i + k; j++) total += nums[j];
    result.push(Math.trunc(total / (2 * k + 1)));
  }
  return result;
}

